-- Quotes, addenda and spec sections belong to the PROJECT, not to the one GC
-- invitation they were filed under.
--
-- EXPAND ONLY. Three nullable columns, one new table, indexes and foreign keys
-- (SET NULL on the new project links, CASCADE on the new table). Nothing is
-- dropped, renamed or tightened, and "bidInvitationId" on each paper keeps
-- working exactly as it did, so the build still serving while this applies
-- cannot be broken by it (CLAUDE.md: a drop and the deploy that stops reading
-- the column do not land together — this has no drop).
--
-- Generated by `prisma migrate diff --from-schema-datamodel <HEAD>
-- --to-schema-datamodel prisma/schema --script` (no database, no shadow
-- database); the backfill at the bottom was added by hand.

-- AlterTable
ALTER TABLE "BidAddendum" ADD COLUMN     "bidProjectId" TEXT;

-- AlterTable
ALTER TABLE "BidQuote" ADD COLUMN     "bidProjectId" TEXT;

