-- Backfill: every existing paper takes the project of the invitation it was
-- filed under.
--
-- IDEMPOTENT: each statement only touches rows whose "bidProjectId" is still
-- NULL, so running the migration's SQL a second time changes nothing — and it
-- never overwrites a project the merge/split code has since set. An invitation
-- with no project (impossible after 20261025120000, which gave every invitation
-- one) leaves its papers NULL, and a NULL paper is still read through its
-- filing invitation.
--
-- NOTHING is backfilled into "BidAddendumAcknowledgement": the legacy
-- "BidAddendum"."acknowledgedOn" already IS the acknowledgement on the filing
-- invitation, which is the only invitation any existing addendum has been
-- shown under. Rows appear there only when a person acknowledges an addendum
-- on ANOTHER GC's bid form.
UPDATE "BidQuote" q
SET "bidProjectId" = i."bidProjectId"
FROM "BidInvitation" i
WHERE q."bidInvitationId" = i."id"
  AND q."bidProjectId" IS NULL
  AND i."bidProjectId" IS NOT NULL;

UPDATE "BidAddendum" a
SET "bidProjectId" = i."bidProjectId"
FROM "BidInvitation" i
WHERE a."bidInvitationId" = i."id"
  AND a."bidProjectId" IS NULL
  AND i."bidProjectId" IS NOT NULL;

UPDATE "BidSpecSection" s
SET "bidProjectId" = i."bidProjectId"
FROM "BidInvitation" i
WHERE s."bidInvitationId" = i."id"
  AND s."bidProjectId" IS NULL
  AND i."bidProjectId" IS NOT NULL;
